-- cpd-migration: additive
-- Incident v2 (hs-d643; contract §2.2 "Incident", commands.md §25): the set of Plans in the
-- incident (`incident_plans`) and the auto-end columns (`until_plan`, `until_pr`) on `incident`.
-- The history triggers of `incident` are regenerated by `reconcile` for the two added columns;
-- `incident_plans` gets its generated triggers from its `history_tables` row (no_delete 0:
-- `incident end` and the auto-end delete every row).
CREATE TABLE incident_plans (
  plan        TEXT PRIMARY KEY REFERENCES plans(id),
  started_txn INTEGER NOT NULL REFERENCES txns(id)
) STRICT;
INSERT INTO history_tables (name, no_delete) VALUES ('incident_plans', 0);
ALTER TABLE incident ADD COLUMN until_plan TEXT;
ALTER TABLE incident ADD COLUMN until_pr TEXT;
